-export async function listTools(){return []}export async function callTool(){return {content:[]}}
+const MODES = ['uppercase', 'lowercase', 'slug'];
+
+export async function listTools() {
+  return [{
+    name: 'text_transform',
+    description: 'Transform text by uppercasing, lowercasing, or slugifying.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        text: { type: 'string', description: 'The text to transform.' },
+        mode: { type: 'string', enum: MODES, description: 'Transform mode: uppercase, lowercase, or slug.' },
+        trim: { type: 'boolean', default: true, description: 'Trim leading/trailing whitespace. Defaults to true.' }
+      },
+      required: ['text', 'mode'],
+      additionalProperties: false
+    }
+  }];
+}
+
+function isObject(v) {
+  return v !== null && typeof v === 'object' && !Array.isArray(v);
+}
+
+function validateArgs(args) {
+  if (!isObject(args)) throw new Error('Arguments must be an object');
+  const allowed = ['text', 'mode', 'trim'];
+  for (const key of Object.keys(args)) {
+    if (!allowed.includes(key)) throw new Error(`Unknown argument: ${key}`);
+  }
+  if (!('text' in args)) throw new Error('Missing required argument: text');
+  if (!('mode' in args)) throw new Error('Missing required argument: mode');
+  const { text, mode, trim = true } = args;
+  if (typeof text !== 'string') throw new Error('text must be a string');
+  if (!MODES.includes(mode)) throw new Error(`mode must be one of ${MODES.join(', ')}`);
+  if ('trim' in args && typeof trim !== 'boolean') throw new Error('trim must be a boolean');
+  return { text, mode, trim };
+}
+
+function transform({ text, mode, trim }) {
+  let s = text;
+  if (trim) s = s.trim();
+  switch (mode) {
+    case 'uppercase':
+      return s.toUpperCase();
+    case 'lowercase':
+      return s.toLowerCase();
+    case 'slug': {
+      let sl = s.toLowerCase();
+      if (trim) sl = sl.trim();
+      sl = sl.replace(/[^a-z0-9]+/g, '-');
+      sl = sl.replace(/^-+|-+$/g, '');
+      return sl;
+    }
+    default:
+      throw new Error(`mode must be one of ${MODES.join(', ')}`);
+  }
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'text_transform') throw new Error(`Unknown tool: ${name}`);
+  const validated = validateArgs(args);
+  const result = transform(validated);
+  return { content: [{ type: 'text', text: result }] };
+}
